-- =========================================================================
-- Enrich portfolio_history with ~1 year of daily snapshots
-- =========================================================================
-- Purpose: the original create_PM_sql.sql only seeds 4 days of
-- portfolio_history (2026-07-22 .. 2026-07-27), so the Performance page's
-- 1M/3M/6M/1Y/MAX range buttons all showed the identical (tiny) window and
-- looked like the same trend. This script backfills ~1 year of daily
-- portfolio value snapshots (business days, 2025-07-01 ..
-- 2026-07-21) using a deterministic seeded random walk that smoothly
-- bridges into the 4 real rows already seeded (2026-07-22 .. 2026-07-27,
-- computed live from the sample price API), so each range button now
-- shows a genuinely different slice/trend of history.
--
-- return_rate is recomputed for EVERY row (including the original 4) as
-- the cumulative return relative to the new earliest date
-- (2025-07-01), replacing the previous baseline of 2026-07-22.
--
-- Safe to re-run: deterministic (fixed random seed) and starts with
-- DELETE FROM portfolio_history, so re-running reproduces the exact same
-- data set rather than appending duplicates.
--
-- How to run:
--   mysql -u root -p prot_manager_DB < src\main\resources\SQL\portfolio_history_enrich_seed.sql
-- =========================================================================

USE prot_manager_DB;

DELETE FROM portfolio_history;


-- Quick check
SELECT COUNT(*) AS portfolio_history_row_count FROM portfolio_history;
SELECT MIN(record_date) AS earliest, MAX(record_date) AS latest FROM portfolio_history;
